def copy_old_profiles(apps, schema_editor):
    """Carry over details saved through the old /uploadprofile/ endpoint."""
    from datetime import date

    UploadProfileFile = apps.get_model("AuthenApp", "UploadProfileFile")
    Profile = apps.get_model("AuthenApp", "Profile")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    for old in UploadProfileFile.objects.all():
        user = User.objects.filter(username=old.UserName).first()
        if user is None or Profile.objects.filter(user=user).exists():
            continue
        try:
            birthday = date.fromisoformat(old.birthday) if old.birthday else None
        except ValueError:
            birthday = None
        gender = old.gender.strip().capitalize()
        Profile.objects.create(
            user=user,
            birthday=birthday,
            phone=old.phone[:20],
            address=old.address,
            gender=gender if gender in ("Female", "Male", "Other") else "",
        )
        if not user.first_name and not user.last_name:
            user.first_name, user.last_name = old.first_name, old.last_name
            user.save(update_fields=["first_name", "last_name"])


